{
  "story": "What happens during mitosis? Start after DNA copying. Follow chromosome copies as they condense, align, and separate. Compare the new nuclei: each receives a matching chromosome set. Use Previous and Next to inspect each stage.",
  "aha": {
    "stateId": "telophase",
    "observation": "Each new nucleus receives an A copy and a B copy because sister copies separate toward opposite poles."
  },
  "layout": {
    "preset": "approved-card",
    "width": 640
  },
  "parts": [
    {
      "id": "stage-rail",
      "kind": "step-rail",
      "presentation": "Place below the explanation and above the experiment. Use short rail labels and show the full active stage name. Keep progress on this rail.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "mitosis-picture",
      "kind": "fixed-picture",
      "presentation": "Use the canonical mitosis composition with a fixed cell boundary. Region phases follow the active rail index in variant.states order. Highlight state.active. Keep chromosome labels visible throughout. Compare the final nuclei side by side at a shared scale. A copies use a solid pattern; B copies use a striped pattern. Assume an idealized animal cell with chromosomes A and B, already replicated. No DNA synthesis, chromosome errors, or cytokinesis occurs here. Copy names identify their eventual pole, not an additional process. Keep all labels readable at native width.",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "links": "variant.links"
      }
    },
    {
      "id": "stage-callout",
      "kind": "active-callout",
      "presentation": "Anchor beside the named target without covering chromosomes. Identify the relevant location and mechanism; leave measurements in the readouts.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "copy-counts-and-status",
      "kind": "value-readout",
      "presentation": "Place counts below the picture, followed by the bound status line. A DNA copy means one chromatid-sized DNA molecule, including joined sisters. Counts are exact integers, not chromosome counts. Left and right groups refer to opposite spindle poles. An em dash means no separated group exists. Balanced parameter-control budget: zero; navigation and Reset are separate.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stage",
      "kind": "index",
      "items": "variant.states",
      "label": "Mitosis stage",
      "presentation": "Provide Previous and Next buttons with those accessible names. Default to the first state; bounds are the first and last states. Advance one state per action. Retain both button names when disabled at boundaries. Every state persists until learner action; never advance automatically. Reference captures show telophase. Support keyboard operation and visible focus."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all defaults. Provide keyboard operation and visible focus."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Mitosis: matching chromosome sets",
        "regions": [
          {
            "id": "cell-boundary",
            "label": "Cell boundary",
            "phases": [
              "Intact outer boundary.",
              "Intact outer boundary.",
              "Intact outer boundary.",
              "Intact outer boundary.",
              "Intact outer boundary.",
              "Intact outer boundary enclosing both new nuclei."
            ]
          },
          {
            "id": "nuclear-envelopes",
            "label": "Nuclear envelopes",
            "phases": [
              "Original envelope surrounds diffuse replicated chromosomes.",
              "Original envelope surrounds condensed paired chromosomes.",
              "Original envelope has broken down.",
              "Envelope absent around aligned chromosome pairs.",
              "Envelope absent around separating chromosome groups.",
              "Separate envelopes surround matching chromosome groups at opposite poles."
            ]
          },
          {
            "id": "spindle",
            "label": "Spindle",
            "phases": [
              "Absent.",
              "Forms outside the original nuclear envelope.",
              "Fibers from opposite poles attach to opposite sisters of each chromosome.",
              "Opposing attachments hold sister pairs at the cell equator.",
              "Attached fibers separate sister copies toward opposite poles.",
              "Disassembles as the new nuclear envelopes form."
            ]
          },
          {
            "id": "a-left",
            "label": "A-left copy",
            "phases": [
              "Diffuse DNA joined to A-right copy inside the original nucleus.",
              "Condensed sister joined to A-right copy.",
              "Joined to A-right copy and attached to the left spindle pole.",
              "At the equator, joined to A-right copy and attached leftward.",
              "Independent chromosome at the left pole.",
              "Decondensing inside the left new nucleus."
            ]
          },
          {
            "id": "a-right",
            "label": "A-right copy",
            "phases": [
              "Diffuse DNA joined to A-left copy inside the original nucleus.",
              "Condensed sister joined to A-left copy.",
              "Joined to A-left copy and attached to the right spindle pole.",
              "At the equator, joined to A-left copy and attached rightward.",
              "Independent chromosome at the right pole.",
              "Decondensing inside the right new nucleus."
            ]
          },
          {
            "id": "b-left",
            "label": "B-left copy",
            "phases": [
              "Diffuse DNA joined to B-right copy inside the original nucleus.",
              "Condensed sister joined to B-right copy.",
              "Joined to B-right copy and attached to the left spindle pole.",
              "At the equator, joined to B-right copy and attached leftward.",
              "Independent chromosome at the left pole.",
              "Decondensing inside the left new nucleus."
            ]
          },
          {
            "id": "b-right",
            "label": "B-right copy",
            "phases": [
              "Diffuse DNA joined to B-left copy inside the original nucleus.",
              "Condensed sister joined to B-left copy.",
              "Joined to B-left copy and attached to the right spindle pole.",
              "At the equator, joined to B-left copy and attached rightward.",
              "Independent chromosome at the right pole.",
              "Decondensing inside the right new nucleus."
            ]
          }
        ],
        "links": [],
        "states": [
          {
            "id": "ready",
            "label": "Before mitosis",
            "short": "Ready",
            "sentence": "Inside the Nuclear envelopes, A-left copy and A-right copy are joined sisters; B-left copy and B-right copy are also joined sisters.",
            "why": "DNA copying has already occurred; mitosis will distribute these existing copies.",
            "active": [
              "nuclear-envelopes"
            ],
            "calloutRegion": "nuclear-envelopes",
            "readouts": [
              {
                "id": "total-copies",
                "label": "DNA copies: whole cell",
                "value": "4"
              },
              {
                "id": "left-copies",
                "label": "DNA copies: left group",
                "value": "—"
              },
              {
                "id": "right-copies",
                "label": "DNA copies: right group",
                "value": "—"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "DNA copied; sister copies remain joined."
              }
            ]
          },
          {
            "id": "prophase",
            "label": "Prophase",
            "short": "Condense",
            "sentence": "A-left copy, A-right copy, B-left copy, and B-right copy condense into visible chromosome pairs while the Spindle forms.",
            "why": "Condensation packages the DNA; sister copies remain joined.",
            "active": [
              "a-left",
              "a-right",
              "b-left",
              "b-right",
              "spindle"
            ],
            "calloutRegion": "a-left",
            "readouts": [
              {
                "id": "total-copies",
