                "value": "4"
              },
              {
                "id": "left-copies",
                "label": "DNA copies: left group",
                "value": "—"
              },
              {
                "id": "right-copies",
                "label": "DNA copies: right group",
                "value": "—"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Chromosomes condense; DNA-copy total stays unchanged."
              }
            ]
          },
          {
            "id": "prometaphase",
            "label": "Prometaphase",
            "short": "Attach",
            "sentence": "The Nuclear envelopes break down, allowing the Spindle to attach opposite sisters to opposite poles.",
            "why": "Opposing attachments prepare each sister pair for separation.",
            "active": [
              "nuclear-envelopes",
              "spindle"
            ],
            "calloutRegion": "spindle",
            "readouts": [
              {
                "id": "total-copies",
                "label": "DNA copies: whole cell",
                "value": "4"
              },
              {
                "id": "left-copies",
                "label": "DNA copies: left group",
                "value": "—"
              },
              {
                "id": "right-copies",
                "label": "DNA copies: right group",
                "value": "—"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Sisters attach toward opposite poles."
              }
            ]
          },
          {
            "id": "metaphase",
            "label": "Metaphase",
            "short": "Align",
            "sentence": "The Spindle holds the A and B sister pairs at the cell equator, with opposite sisters attached toward opposite poles.",
            "why": "Each pole is connected to a copy of every chromosome type.",
            "active": [
              "spindle",
              "a-left",
              "a-right",
              "b-left",
              "b-right"
            ],
            "calloutRegion": "spindle",
            "readouts": [
              {
                "id": "total-copies",
                "label": "DNA copies: whole cell",
                "value": "4"
              },
              {
                "id": "left-copies",
                "label": "DNA copies: left group",
                "value": "—"
              },
              {
                "id": "right-copies",
                "label": "DNA copies: right group",
                "value": "—"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Sister pairs align; copies remain joined."
              }
            ]
          },
          {
            "id": "anaphase",
            "label": "Anaphase",
            "short": "Separate",
            "sentence": "The Spindle separates A-left copy and B-left copy from A-right copy and B-right copy toward opposite poles.",
            "why": "Released sister copies become independent chromosomes; separation redistributes DNA without making more.",
            "active": [
              "a-left",
              "a-right",
              "b-left",
              "b-right"
            ],
            "calloutRegion": "a-left",
            "readouts": [
              {
                "id": "total-copies",
                "label": "DNA copies: whole cell",
                "value": "4"
              },
              {
                "id": "left-copies",
