                "value": "2"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Matching chromosome groups reach opposite poles."
              }
            ]
          },
          {
            "id": "telophase",
            "label": "Telophase",
            "short": "Re-form",
            "sentence": "The Nuclear envelopes re-form around matching A and B sets; chromosome copies decondense and the Spindle disassembles.",
            "why": "Compare the new nuclei: each contains the same chromosome types. Cytokinesis divides the cell and is not shown.",
            "active": [
              "nuclear-envelopes",
              "a-left",
              "a-right",
              "b-left",
              "b-right"
            ],
            "calloutRegion": "nuclear-envelopes",
            "readouts": [
